// IL2067: unknown whether t has a constructor
static object Make(Type t) => Activator.CreateInstance(t)!;

// annotation: "keep the public parameterless constructor"
static object Make2(
    [DynamicallyAccessedMembers(DynamicallyAccessedMemberTypes.PublicParameterlessConstructor)]
    Type t) => Activator.CreateInstance(t)!;

Make2(typeof(Order));   // ok: the Order() constructor is kept
